"""inventory.yml: the probe host list, generated by discover.sh."""
from pathlib import Path

HERE = Path(__file__).resolve().parent
INVENTORY = HERE / "inventory.yml"
SUFFIXES = (".ib", ".inband", ".lb", "-mgmt")   # LDAP wrappers, not hosts
CLASSES = ("core", "fstor", "hstor", "eofe", "fcstor", "nfs")
MEDIA = {"fstor": "flash", "hstor": "hdd"}
FILESYSTEMS = ("zfs", "xfs", "mixed")
HEADER = """# inventory.yml - ORCD NFS filers: the probe host list. Generated by
# discover.sh --ldap (hosts) and --pull-facts (tags); a host that leaves
# LDAP is kept until removed by hand. Tags: class (name), media (name),
# fs (shares.backing)."""


def clean_host(name):
    """Clean host name: fstor010-p2.ib and fstor010-mgmt -> fstor010."""
    for suffix in SUFFIXES:
        if name.endswith(suffix):
            name = name[:-len(suffix)]
    return name[:-3] if name.endswith("-p2") else name


def load():
    """{host: [tags]} from the file; ValueError on any other shape."""
    hosts, current = {}, None
    for number, raw in enumerate(INVENTORY.read_text().splitlines(), 1):
        line = raw.split("#", 1)[0].rstrip()
        if not line.strip() or line.strip() == "hosts:":
            continue
        indent, field = len(line) - len(line.lstrip()), line.strip()
        if indent == 2 and field.endswith(":"):
            current = field[:-1]
            hosts[current] = []
        elif indent == 4 and field.startswith("tags:") and current:
            hosts[current] = [t.strip() for t in
                              field[5:].strip(" []").split(",") if t.strip()]
        else:
            raise ValueError(f"{INVENTORY.name}:{number}: cannot parse {line!r}")
    return hosts


def save(hosts):
    lines = [HEADER, "hosts:"]
    for host in sorted(hosts):
        lines += [f"  {host}:", f"    tags: [{', '.join(hosts[host])}]"]
    INVENTORY.write_text("\n".join(lines) + "\n")


def merge_tags(host, old, fs=None):
    """Class and media follow the name; fs needs facts, else keep the old."""
    cls = next((tag for tag in CLASSES if host.startswith(tag)), None)
    fs = fs or next((tag for tag in old if tag in FILESYSTEMS), None)
    return [tag for tag in (cls, MEDIA.get(cls), fs) if tag]
